def run(j):
 if Path(j['out']).exists():return(j['id'],'existing')
 cmd=[sys.executable,CLI,'edit']
 for ref in j['references']:cmd+=['--image',ref]
 cmd+=['--prompt-file',j['prompt_file'],'--model','gpt-image-2','--quality','high','--size',j['size'],'--no-augment','--out',j['out']]
 t=time.time();r=subprocess.run(cmd,capture_output=True,text=True,encoding='utf8',errors='replace')
 Path(f'D:/CodexData/Temp/P2-9/{j["id"]}.log').write_text(r.stdout+'\n'+r.stderr,encoding='utf8')
 print(j['id'],r.returncode,round(time.time()-t),flush=True)
 return(j['id'],r.returncode)
if __name__=='__main__':
 with ThreadPoolExecutor(max_workers=2)as pool:
  for f in as_completed([pool.submit(run,j)for j in jobs]):f.result()

